import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../widgets/erp_quick_task_button.dart';
class ErpGeographicDataScreen extends StatefulWidget {
 const ErpGeographicDataScreen({super.key,required this.companyId}); final String? companyId;
 @override State<ErpGeographicDataScreen> createState()=>_ErpGeographicDataScreenState();
}
class _ErpGeographicDataScreenState extends State<ErpGeographicDataScreen>{
 SupabaseClient? db; List<Map<String,dynamic>> rows=[]; String? error,message; bool loading=false;
 String s(dynamic v)=>(v??'').toString(); String label(String l)=>l=='governorate'?'محافظة':l=='district'?'حي أو مركز':'منطقة أو قرية'; String child(String l)=>l=='governorate'?'district':'area';
 @override void initState(){super.initState();try{db=Supabase.instance.client;}catch(_){}load();}
 Future<void> load() async {final c=(widget.companyId??'').trim();if(db==null||c.isEmpty){setState(()=>error='لا توجد شركة نشطة أو اتصال بقاعدة البيانات.');return;}setState(()=>loading=true);try{final x=await db!.from('erp_geographic_data').select('id,parent_id,geo_code,name_ar,name_en,level,is_active').eq('company_id',c).order('geo_code');if(!mounted)return;setState(()=>{rows=(x as List).map((e)=>Map<String,dynamic>.from(e)).toList(),loading=false,error=null});}catch(e){if(mounted)setState(()=>{loading=false,error='تعذر تحميل البيانات. شغّل ترحيل erp_geographic_data_schema.sql: $e'});}}
 Future<void> edit({Map<String,dynamic>? row,String? parent,required String level}) async {
 final code=TextEditingController(text:s(row?['geo_code'])),ar=TextEditingController(text:s(row?['name_ar'])),en=TextEditingController(text:s(row?['name_en']));var active=row?['is_active']!=false;
 final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,refresh)=>AlertDialog(title:Text(row==null?'إضافة ${label(level)}':'تعديل ${label(level)}'),content:SizedBox(width:420,child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:code,decoration:InputDecoration(labelText:'كود ${label(level)} *')),TextField(controller:ar,decoration:const InputDecoration(labelText:'الاسم بالعربي *')),TextField(controller:en,decoration:const InputDecoration(labelText:'الاسم بالإنجليزي')),CheckboxListTile(value:active,onChanged:(v)=>refresh(()=>active=v??false),title:const Text('نشط'),controlAffinity:ListTileControlAffinity.leading)])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('حفظ'))])));
 if(ok!=true){code.dispose();ar.dispose();en.dispose();return;}try{if(code.text.trim().isEmpty||ar.text.trim().isEmpty)throw ArgumentError('الكود والاسم العربي مطلوبان.');final c=(widget.companyId??'').trim();final data=<String,Object?>{'company_id':c,'parent_id':parent,'geo_code':code.text.trim(),'name_ar':ar.text.trim(),'name_en':en.text.trim().isEmpty?null:en.text.trim(),'level':level,'is_active':active};if(row==null){await db!.from('erp_geographic_data').insert(data);}else{await db!.from('erp_geographic_data').update(data).eq('id',row['id']).eq('company_id',c);}if(mounted)setState(()=>message='تم حفظ البيانات.');await load();}catch(e){if(mounted)setState(()=>error='تعذر الحفظ: $e');}finally{code.dispose();ar.dispose();en.dispose();}}
 Future<void> toggle(Map<String,dynamic> r)async{try{await db!.from('erp_geographic_data').update({'is_active':r['is_active']!=true}).eq('id',r['id']).eq('company_id',(widget.companyId??'').trim());await load();}catch(e){setState(()=>error='تعذر تغيير الحالة: $e');}}
 Future<void> remove(Map<String,dynamic> r)async{final id=s(r['id']),has=rows.any((x)=>s(x['parent_id'])==id);final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(title:const Text('حذف بيانات جغرافية'),content:Text(has?'لا يمكن حذف سجل له بيانات تابعة.':'هل تريد حذف «'+s(r['name_ar'])+'»؟'),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),if(!has)FilledButton(style:FilledButton.styleFrom(backgroundColor:Colors.red),onPressed:()=>Navigator.pop(ctx,true),child:const Text('حذف'))]));if(ok!=true)return;try{await db!.from('erp_geographic_data').delete().eq('id',id).eq('company_id',(widget.companyId??'').trim());await load();}catch(e){setState(()=>error='تعذر الحذف: $e');}}
 Widget task(String t,IconData i,Color c,VoidCallback? f)=>ErpQuickTaskButton(label:t,icon:i,onPressed:f,fallbackColor:c);
 Widget node(Map<String,dynamic> r,int depth){final id=s(r['id']),lev=s(r['level']);final kids=rows.where((x)=>s(x['parent_id'])==id).toList();return Padding(padding:EdgeInsetsDirectional.only(start:depth*22,bottom:5),child:Card(child:Column(children:[Row(children:[SizedBox(width:32,child:Text((rows.indexOf(r)+1).toString())),Expanded(flex:2,child:Text(s(r['geo_code']))),Expanded(flex:4,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(s(r['name_ar']),style:const TextStyle(fontWeight:FontWeight.bold)),Text(s(r['name_en'])),Text(label(lev),style:const TextStyle(fontSize:10,color:Color(0xFF3E007D)))])),Checkbox(value:r['is_active']==true,onChanged:(_)=>toggle(r)),if(lev!='area')IconButton(tooltip:'إضافة تابع',onPressed:()=>edit(parent:id,level:child(lev)),icon:const Icon(Icons.add_circle,color:Color(0xFF3E007D))),IconButton(tooltip:'تعديل',onPressed:()=>edit(row:r,parent:s(r['parent_id']).isEmpty?null:s(r['parent_id']),level:lev),icon:const Icon(Icons.edit,color:Color(0xFFFFA015))),IconButton(tooltip:'حذف',onPressed:()=>remove(r),icon:const Icon(Icons.delete_forever,color:Colors.red))]),if(kids.isNotEmpty)Padding(padding:const EdgeInsets.all(6),child:Column(children:kids.map((x)=>node(x,depth+1)).toList()))])));}
 @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Card(color:const Color(0xFF3E007D),child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('بيانات جغرافية',style:TextStyle(color:Colors.white,fontSize:21,fontWeight:FontWeight.w900)),const Text('شجرة المحافظات ثم الأحياء والمراكز ثم المناطق والقرى.',style:TextStyle(color:Colors.white70)),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[task('تحديث',Icons.refresh,Colors.blue,loading?null:load),task('إضافة محافظة',Icons.add_location_alt,const Color(0xFF168447),()=>edit(level:'governorate')),task('معاينة',Icons.preview_outlined,const Color(0xFFFFA015),()=>showDialog<void>(context:context,builder:(ctx)=>AlertDialog(title:const Text('معاينة'),content:Text('عدد السجلات: '+rows.length.toString()),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('إغلاق'))])))]))]))),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),if(message!=null)Text(message!,style:const TextStyle(color:Colors.green)),if(loading)const LinearProgressIndicator(),Expanded(child:ListView(children:rows.where((r)=>s(r['level'])=='governorate'&&s(r['parent_id']).isEmpty).map((r)=>node(r,0)).toList()))]));
}
